import { ComponentFixture, TestBed } from '@angular/core/testing';
import { MainComponent } from './main.component';
import { of, throwError } from 'rxjs';
import { EMPTY } from 'rxjs';
import { FormBuilder, ReactiveFormsModule } from '@angular/forms';
import { LoaderComponent } from '../loader/loader.component'; // Asegúrate de importar correctamente el LoaderComponent
import { RecaptchaService } from '../services/recaptcha.service'; // Asegúrate de importar correctamente el RecaptchaService

describe('MainComponent', () => {
  let component: MainComponent;
  let fixture: ComponentFixture<MainComponent>;
  let loaderComponent: LoaderComponent;
  let recaptchaService: RecaptchaService;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      declarations: [MainComponent, LoaderComponent],
      imports: [ReactiveFormsModule],
      providers: [
        FormBuilder,
        {
          provide: RecaptchaService,
          useValue: {
            handleRecaptcha: jest.fn(),
          },
        },
      ],
    }).compileComponents();
  });

  beforeEach(() => {
    fixture = TestBed.createComponent(MainComponent);
    component = fixture.componentInstance;
    loaderComponent = TestBed.inject(LoaderComponent);
    recaptchaService = TestBed.inject(RecaptchaService);

    component.customerForm = new FormBuilder().group({
      // Define your form controls here
    });

    jest.spyOn(loaderComponent, 'show');
    jest.spyOn(loaderComponent, 'hide');
    jest.spyOn(component, 'handleError');
    jest.spyOn(component, 'handleSuccess');
    jest.spyOn(recaptchaService, 'handleRecaptcha').mockReturnValue(of({}));

    fixture.detectChanges();
  });

  it('should show loader and handle success on valid form submission', () => {
    component.customerForm.setValue({
      // Set valid form values here
    });

    component.submited$.next();

    expect(loaderComponent.show).toHaveBeenCalled();
    expect(recaptchaService.handleRecaptcha).toHaveBeenCalled();
    expect(component.handleSuccess).toHaveBeenCalled();
    expect(loaderComponent.hide).toHaveBeenCalled();
  });

  it('should handle error and hide loader on recaptcha error', () => {
    jest.spyOn(recaptchaService, 'handleRecaptcha').mockReturnValue(throwError('error'));

    component.customerForm.setValue({
      // Set valid form values here
    });

    component.submited$.next();

    expect(loaderComponent.show).toHaveBeenCalled();
    expect(recaptchaService.handleRecaptcha).toHaveBeenCalled();
    expect(component.handleError).toHaveBeenCalledWith('error');
    expect(loaderComponent.hide).toHaveBeenCalled();
  });

  it('should not submit if form is invalid', () => {
    component.customerForm.setValue({
      // Set invalid form values here
    });

    component.submited$.next();

    expect(loaderComponent.show).not.toHaveBeenCalled();
    expect(recaptchaService.handleRecaptcha).not.toHaveBeenCalled();
    expect(component.handleSuccess).not.toHaveBeenCalled();
    expect(component.handleError).not.toHaveBeenCalled();
    expect(loaderComponent.hide).not.toHaveBeenCalled();
  });
});
